package main

import (
	"bytes"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

const testModule = "example.com/service"

func TestMergeProfiles(t *testing.T) {
	root := t.TempDir()
	writeFixture(t, root, "internal/handler.go", "package internal\n\n// Code generated by example. DO NOT EDIT.\n")
	writeFixture(t, root, "internal/generated.go", "//go:build linux\n\n// Code generated by example. DO NOT EDIT.\n\npackage internal\n")
	writeFixture(t, root, "cmd/service/main.go", "package main\n")
	unit := writeFixture(t, root, "unit.out", `mode: atomic
example.com/service/internal/handler.go:4.1,4.8 2 3
example.com/service/internal/handler.go:4.1,4.8 2 1
example.com/service/internal/handler.go:5.1,5.8 1 0
example.com/service/internal/generated.go:6.1,6.8 20 0
`)
	integration := writeFixture(t, root, "integration.out", `mode: atomic
example.com/service/internal/handler.go:4.1,4.8 2 4
example.com/service/internal/handler.go:5.1,5.8 1 1
example.com/service/cmd/service/main.go:2.1,2.8 4 0
example.com/service/internal/generated.go:6.1,6.8 20 5
`)

	var out bytes.Buffer
	if err := mergeProfiles(&out, root, testModule, []string{unit, integration}); err != nil {
		t.Fatal(err)
	}
	want := `mode: atomic
example.com/service/cmd/service/main.go:2.1,2.8 4 0
example.com/service/internal/handler.go:4.1,4.8 2 8
example.com/service/internal/handler.go:5.1,5.8 1 1
`
	if got := out.String(); got != want {
		t.Fatalf("merged profile =\n%s\nwant\n%s", got, want)
	}
}

func TestMergeProfilesRejectsInconsistentInputs(t *testing.T) {
	root := t.TempDir()
	writeFixture(t, root, "handler.go", "package service\n")
	unit := writeFixture(t, root, "unit.out", "mode: atomic\nexample.com/service/handler.go:4.1,4.8 2 3\n")

	for _, test := range []struct {
		name    string
		profile string
		want    string
	}{
		{
			name:    "statement count",
			profile: "mode: atomic\nexample.com/service/handler.go:4.1,4.8 3 1\n",
			want:    "statement count",
		},
		{
			name:    "coverage mode",
			profile: "mode: set\nexample.com/service/handler.go:4.1,4.8 2 1\n",
			want:    "mode: atomic",
		},
		{
			name:    "missing source",
			profile: "mode: atomic\nexample.com/service/missing.go:4.1,4.8 2 1\n",
			want:    "missing.go",
		},
	} {
		t.Run(test.name, func(t *testing.T) {
			integration := writeFixture(t, root, "integration.out", test.profile)
			var out bytes.Buffer
			if err := mergeProfiles(&out, root, testModule, []string{unit, integration}); err == nil || !strings.Contains(err.Error(), test.want) {
				t.Fatalf("mergeProfiles error = %v, want %q", err, test.want)
			}
			if out.Len() != 0 {
				t.Fatal("wrote incomplete coverage profile")
			}
		})
	}
}

func writeFixture(t *testing.T, root, name, content string) string {
	t.Helper()
	file := filepath.Join(root, name)
	if err := os.MkdirAll(filepath.Dir(file), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(file, []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
	return file
}
